def count_neighbors(board):
    total = np.zeros_like(board)
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if (dy, dx) != (0, 0):
                total += np.roll(board, (dy, dx), axis=(0, 1))
    return total

def step(board):
    n = count_neighbors(board)
    born = (board == 0) & (n == 3)
    survive = (board == 1) & ((n == 2) | (n == 3))
    return (born | survive).astype(int)

blinker = np.zeros((5, 5), dtype=int)
blinker[2, 1:4] = 1
show(step(blinker))
--- test
