    case 3:
    case 4:
    case 5:
        type = "weekday";
        break;
    case 6:
    case 7:
        type = "weekend";
        break;
    default:
        type = "unknown";
}
--- test
__check(type.equals("weekend"), "Day 6 is a weekend day");
--- hint
