    boolean done;
    Task(boolean done) { this.done = done; }
}

class TodoList {
    ArrayList<Task> tasks = new ArrayList<>();

    int remaining() {
        return tasks.size();
    }
}

public class Main {
    public static void main(String[] args) {
        TodoList list = new TodoList();
        list.tasks.add(new Task(true));
