  }
  .eyebrow { margin: 0 0 .3rem; color: #0f766e; font-size: .72rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
  h2 { margin: 0 0 .5rem; font-size: 1.35rem; color: #0f172a; }
