INSERT INTO reviews (id, user_id, course_id, rating, title, body, created_at, updated_at) VALUES
('rev_seed0000k1', 'usr_seed000000', 'crs_computer_vision_bootcamp', 5, 'Helped me land an ML role', 'I was a backend engineer trying to move into ML. This course gave me the vocabulary and the hands-on confidence to pass technical interviews. Highly recommended.', '2026-10-15T13:40:00.179Z', '2026-10-15T13:40:00.179Z'),
('rev_seed0000k2', 'usr_seed000000', 'crs_llm_engineering', 5, 'Best course I''ve taken on the topic', 'The explanations build intuition before the math, and every concept is backed by code you actually run. I finally understand what''s happening under the hood instead of copying snippets.', '2026-10-12T20:40:00.179Z', '2026-10-12T20:40:00.179Z'),
('rev_seed0000k3', 'usr_seed000000', 'crs_python_for_data_science', 5, 'Great instructor, great community', 'Questions in the Q&A got thoughtful answers quickly. The notes feature and lesson resources made it easy to review before my exam.', '2026-08-01T06:40:00.179Z', '2026-08-01T06:40:00.179Z'),
('rev_seed0000k4', 'usr_seed000001', 'crs_python_for_data_science', 5, 'Dense but fantastic', 'This is not a fluffy overview — it goes deep. Expect to pause and re-watch, but the payoff is real. The instructor clearly knows the material at a research level.', '2026-07-30T10:40:00.179Z', '2026-07-30T10:40:00.179Z'),
('rev_seed0000k5', 'usr_seed000003', 'crs_numpy_mastery', 5, 'Dense but fantastic', 'This is not a fluffy overview — it goes deep. Expect to pause and re-watch, but the payoff is real. The instructor clearly knows the material at a research level.', '2026-08-07T07:40:00.179Z', '2026-08-07T07:40:00.179Z'),
('rev_seed0000k6', 'usr_seed000004', 'crs_python_basics', 5, 'Finally clicked', 'I''d tried learning this from scattered blog posts and papers. Having a single coherent narrative with good visuals made it click. The capstone tied everything together.', '2026-10-22T02:40:00.179Z', '2026-10-22T02:40:00.179Z'),
('rev_seed0000k7', 'usr_seed000006', 'crs_c_basics', 5, 'Dense but fantastic', 'This is not a fluffy overview — it goes deep. Expect to pause and re-watch, but the payoff is real. The instructor clearly knows the material at a research level.', '2026-08-31T07:40:00.179Z', '2026-08-31T07:40:00.179Z'),
('rev_seed0000k8', 'usr_seed000006', 'crs_generative_ai_diffusion', 4, 'Finally clicked', 'I''d tried learning this from scattered blog posts and papers. Having a single coherent narrative with good visuals made it click. The capstone tied everything together.', '2026-10-20T15:40:00.179Z', '2026-10-20T15:40:00.179Z'),
